contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address intermediate) public payable {
        require(intermediate != address(this));
        require(c.owner() == address(this));
        c.setOwner(intermediate); if (__ESBMC_reverted()) return;
        c.setOwner(address(this)); if (__ESBMC_reverted()) return;
        assert(c.owner() == address(this));
    }
    receive() external payable {}
}

