// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(address intermediate) internal {
        vm.assume(intermediate != address(this));
        vm.assume(c.owner() == address(this));
        try c.setOwner(intermediate) {} catch { return; }
        try c.setOwner(address(this)) {} catch { return; }
        assertTrue(c.owner() == address(this));
    }

    function testFuzz_run(address intermediate) public {
        vm.assume(intermediate.code.length == 0 && uint160(intermediate) > 0xffff && intermediate != address(this) && intermediate != address(c) && intermediate != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && intermediate != 0x000000000000000000636F6e736F6c652e6c6f67 && intermediate != 0x4e59b44847b379578588920cA78FbF26c0B4956C && intermediate != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(intermediate);
    }

    receive() external payable {}
}
